            "title": {
              "type": "string",
              "description": "下一条日程标题",
              "sampleValue": "产品评审"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间",
              "sampleValue": "10:00"
            }
          }
        ]
      }
    },
